&lt;tr&gt;
&lt;td&gt;Helper contract&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0x6161a9ca16f213c3373c07bcc0c4b4a4705340be&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Victim pool (BiswapPoolV3 WBNB/BUSD)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0xc83f96f87f586a858a14c89e16434460bac0b643&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;WBNB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0xbb4cdb9cbd36b01bd1cbaebf2de08d9173bc095c&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Legacy BUSD&lt;/td&gt;
&lt;td&gt;&lt;code&gt;0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Flash loan source&lt;/td&gt;
&lt;td&gt;PancakeSwap V3 USDT/WBNB 0.01% pool, &lt;code&gt;0x172fcd41e0913e95784454622d1c3724f546f849&lt;/code&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Flash loan / repayment&lt;/td&gt;
&lt;td&gt;11,283 WBNB borrowed; 11,284.1283 WBNB repaid (0.01% fee)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Mispriced swap&lt;/td&gt;
&lt;td&gt;11,283.277957284066035619 WBNB out for 63,263 wei BUSD in&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Attacker payout&lt;/td&gt;
&lt;td&gt;50,553.922841094381842 BUSD&lt;/td&gt;
&lt;/tr&gt;
